using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<Notebook>();

builder.Services.AddChatClient(pipeline => pipeline
    .UseLogging()
    .Use(innerClient => new OpenAI.ChatGPTClient(innerClient))
    ?? throw new InvalidOperationException("Failed to build chat client pipeline"));

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(pipeline => pipeline
    .UseLogging()
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();
var logger = host.Services.GetRequiredService<ILoggerFactory>()
    .CreateLogger("ResearchAgent");

// Define the tools the agent can use
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")] string query
        ) =>
        {
            logger.LogDebug("WebSearch invoked: Query={Query}", query);
            return WebSearchSimulator.SearchAsync(query);
        },
        "WebSearch",
        "Searches the web for information on a given query and returns relevant results."),

    AIFunctionFactory.Create(
        (
            [Description("A short descriptive title for the note")] string title,
            [Description("The content to save in the note")] string content
        ) =>
        {
            notebook.Add(title, content);
            logger.LogDebug("Note saved: {Title}", title);
            return $"Note saved: \"{title}\"";
        },
        "SaveNote",
        "Saves a note with a title and content for later reference in the final summary."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAll();
            logger.LogDebug("Notes retrieved: Count={Count}", notes.Count);
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "GetNotes",
        "Retrieves all previously saved notes to help compile the final summary.")
};

const string instructions = """
    You are a research agent. Your job is to research a topic thoroughly and produce a
    well-organized summary. Follow this process:

    1. Use the WebSearch tool to find information about the topic. Perform multiple
       searches with different queries to get comprehensive coverage.
    2. Use the SaveNote tool to record key findings as you go — include facts, statistics,
       and source URLs. Save at least 3 notes from different angles.
    3. Use the GetNotes tool to review everything you have gathered.
    4. Produce a final, well-structured summary that synthesizes all your research notes.
       Include section headers and cite sources where available.

    Always search before summarizing. Never fabricate information that was not returned
    by a search.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

// Prompt for a research topic
Console.Write("Enter a research topic (or press Enter for a default): ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    topic = "recent advances in quantum computing";
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 60));
Console.WriteLine();

// Run the agent with streaming output
await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    })))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();
Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine($"Research complete. {notebook.GetAll().Count} note(s) saved during research.");

// --- Supporting types ---

/// <summary>
/// Simple in-memory notebook for storing research findings.
/// </summary>
sealed class Notebook
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add(new Note(title, content));

    public IReadOnlyList<Note> GetAll() => _notes.AsReadOnly();
}

record Note(string Title, string Content);

/// <summary>
/// Simulates web search results for demonstration purposes.
/// Replace with a real search API (e.g., Bing Search) for production use.
/// </summary>
static class WebSearchSimulator
{
    private static readonly Dictionary<string, string[]> s_knowledgeBase = new(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "Result 1: IBM unveiled its 1,121-qubit Condor processor in December 2023, the largest gate-based quantum processor to date. IBM's roadmap targets 100,000 qubits by 2033. (Source: IBM Research Blog)",
            "Result 2: Google's Willow chip (2024) demonstrated quantum error correction below the surface-code threshold for the first time, solving a challenge that has been outstanding for nearly 30 years. (Source: Google AI Blog)",
            "Result 3: Microsoft announced its topological qubit breakthrough in February 2025, achieving the first reliable topological qubit that promises fundamentally lower error rates. (Source: Microsoft Azure Quantum Blog)",
        ],
        ["quantum computing applications"] =
        [
            "Result 1: Pharmaceutical companies are using quantum simulation to model molecular interactions for drug discovery. Roche partnered with Cambridge Quantum in 2024 to explore protein folding. (Source: Nature Reviews Drug Discovery)",
            "Result 2: JPMorgan Chase and Goldman Sachs have invested in quantum algorithms for portfolio optimization and risk analysis, achieving speed-ups in Monte Carlo simulations. (Source: Financial Times)",
            "Result 3: Quantum key distribution (QKD) networks are being deployed in China and Europe for ultra-secure communications, with China's 4,600 km quantum network operational since 2023. (Source: Science Magazine)",
        ],
        ["quantum computing challenges"] =
        [
            "Result 1: Decoherence remains the primary obstacle — current qubits lose their quantum state within milliseconds, requiring extensive error correction overhead. (Source: Physical Review Letters)",
            "Result 2: The current cost of quantum computing hardware is prohibitive: a single dilution refrigerator costs $1-2 million, and operating temperatures must be maintained near absolute zero (15 millikelvins). (Source: IEEE Spectrum)",
            "Result 3: The quantum talent gap is significant — a 2024 McKinsey report estimates the industry needs 3x more quantum engineers than are currently available worldwide. (Source: McKinsey Quarterly)",
        ],
    };

    public static Task<string> SearchAsync(string query)
    {
        // Find the best matching key
        var bestMatch = s_knowledgeBase.Keys
            .Where(key => query.Contains(key, StringComparison.OrdinalIgnoreCase)
                       || key.Contains(query, StringComparison.OrdinalIgnoreCase))
            .FirstOrDefault();

        if (bestMatch is not null)
        {
            return Task.FromResult(string.Join("\n", s_knowledgeBase[bestMatch]));
        }

        // Generic fallback results for any topic
        return Task.FromResult(
            $"""
            Result 1: "{query}" is an active area of research with significant developments in 2024-2025. Multiple academic institutions and companies are contributing to advances in this field. (Source: arXiv.org)
            Result 2: A comprehensive review published in Nature (2024) covers the latest breakthroughs and remaining challenges in {query}. Key trends include increased funding, international collaboration, and open-source tooling. (Source: Nature)
            Result 3: Industry analysts project the {query} market will grow substantially over the next decade, driven by enterprise adoption and government investment programs. (Source: Gartner)
            """);
    }
}

