16. var notebook = new Notebook();
17. 
18. // Define the tools the agent can use
19. var tools = new AITool[]
20. {
21.     AIFunctionFactory.Create(
22.         (
23.             [Description("The search query to look up on the web")] string query
24.         ) =>
25.         {
26.             Console.ForegroundColor = ConsoleColor.DarkGray;
27.             Console.WriteLine($"  [tool] WebSearch: \"{query}\"");
28.             Console.ResetColor();
29.             return WebSearchSimulator.SearchAsync(query);
30.         },
31.         "WebSearch",
32.         "Searches the web for information on a given query and returns relevant results."),
33. 
34.     AIFunctionFactory.Create(
35.         (
36.             [Description("A short descriptive title for the note")] string title,
37.             [Description("The content to save in the note")] string content
38.         ) =>
39.         {
40.             notebook.Add(title, content);
41.             Console.ForegroundColor = ConsoleColor.DarkGray;
42.             Console.WriteLine($"  [tool] SaveNote: \"{title}\"");
43.             Console.ResetColor();
44.             return $"Note saved: \"{title}\"";
45.         },
46.         "SaveNote",
47.         "Saves a note with a title and content for later reference in the final summary."),
48. 
49.     AIFunctionFactory.Create(
50.         () =>
51.         {
52.             var notes = notebook.GetAll();
53.             Console.ForegroundColor = ConsoleColor.DarkGray;
54.             Console.WriteLine($"  [tool] GetNotes: {notes.Count} note(s)");
55.             Console.ResetColor();
56.             return notes.Count == 0
57.                 ? "No notes saved yet."
58.                 : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
59.         },
60.         "GetNotes",
61.         "Retrieves all previously saved notes to help compile the final summary.")
62. };
63. 
64. const string instructions = """
65.     You are a research agent. Your job is to research a topic thoroughly and produce a
66.     well-organized summary. Follow this process:
67. 
68.     1. Use the WebSearch tool to find information about the topic. Perform multiple
69.        searches with different queries to get comprehensive coverage.
70.     2. Use the SaveNote tool to record key findings as you go — include facts, statistics,
71.        and source URLs. Save at least 3 notes from different angles.
72.     3. Use the GetNotes tool to review everything you have gathered.
73.     4. Produce a final, well-structured summary that synthesizes all your research notes.
74.        Include section headers and cite sources where available.
75. 
76.     Always search before summarizing. Never fabricate information that was not returned
77.     by a search.
78.     """;
79. 
80. var agent = new ChatClientAgent(
81.     chatClient,
82.     instructions: instructions,
83.     name: "ResearchAgent",
84.     description: "An agent that researches topics by searching the web and taking notes.",
85.     tools: tools);
86. 
87. // Prompt for a research topic
88. Console.Write("Enter a research topic (or press Enter for a default): ");
89. var topic = Console.ReadLine()?.Trim();
90. if (string.IsNullOrWhiteSpace(topic))
91. {
92.     topic = "recent advances in quantum computing";
93. }
94. 
95. Console.WriteLine();
96. Console.WriteLine($"Researching: {topic}");
97. Console.WriteLine(new string('─', 60));
98. Console.WriteLine();
99. 
100. // Run the agent with streaming output
101. await foreach (var update in agent.RunStreamingAsync(
102.     $"Research the following topic and provide a comprehensive summary: {topic}",
