             "Result 3: The quantum talent gap is significant — a 2024 McKinsey report estimates the industry needs 3x more quantum engineers than are currently available worldwide. (Source: McKinsey Quarterly)",
         ],
     };

     public static Task<string> SearchAsync(string query)
     {
         // Find the best matching key
         var bestMatch = s_knowledgeBase.Keys
             .Where(key => query.Contains(key, StringComparison.OrdinalIgnoreCase)
                        || key.Contains(query, StringComparison.OrdinalIgnoreCase))
             .FirstOrDefault();

         if (bestMatch is not null)
         {
             return Task.FromResult(string.Join("\n", s_knowledgeBase[bestMatch]));
         }

         // Generic fallback results for any topic
         return Task.FromResult(
             $"""
             Result 1: "{query}" is an active area of research with significant developments in 2024-2025. Multiple academic institutions and companies are contributing to advances in this field. (Source: arXiv.org)
             Result 2: A comprehensive review published in Nature (2024) covers the latest breakthroughs and remaining challenges in {query}. Key trends include increased funding, international collaboration, and open-source tooling. (Source: Nature)
             Result 3: Industry analysts project the {query} market will grow substantially over the next decade, driven by enterprise adoption and government investment programs. (Source: Gartner)
             """);
     }
 }
